            [ordered]@{ name = $_.Name; isDefault = $_.IsDefault; parameters = @($_.Parameters | Sort-Object Name | ForEach-Object { [ordered]@{ name = $_.Name; type = $_.ParameterType.FullName; mandatory = $_.IsMandatory } }) }
